SELECT CONCAT_WS(CHAR(10 USING utf8), b.data, m.murtad) AS data
FROM (
SELECT 
  CASE
    WHEN IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag.abt_data_teks WHERE no_var=1214 AND perkara_id='#perkara_id#') USING utf8),'\\','/'),'"','&quot;'),'''','&#39;'),'') REGEXP 'KTP|Kartu Tanda Penduduk' THEN
      "Menimbang, bahwa bukti P.1 dan P.2 merupakan fotokopi akta autentik yang telah bermeterai cukup, di-nazegelen, dan telah dicocokkan dengan aslinya yang ternyata sesuai, serta isinya relevan dengan pokok perkara, sehingga bukti-bukti tersebut telah memenuhi syarat formil dan materiil sebagai alat bukti, dan sesuai Pasal 285 RBg mempunyai kekuatan pembuktian yang sempurna dan mengikat;"
    WHEN IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag.abt_data_teks WHERE no_var=1214 AND perkara_id='#perkara_id#') USING utf8),'\\','/'),'"','&quot;'),'''','&#39;'),'') REGEXP 'Domisili' OR IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag.abt_data_teks WHERE no_var=8503 AND perkara_id='#perkara_id#') USING utf8),'\\','/'),'"','&quot;'),'''','&#39;'),'') REGEXP 'Berdomisili' THEN
      "Menimbang, bahwa bukti P.1 dan P.2 telah bermeterai cukup, di-nazegelen, dan telah dicocokkan dengan aslinya yang ternyata sesuai, serta isinya relevan dengan pokok perkara, sehingga bukti-bukti tersebut telah memenuhi syarat formil dan materiil sebagai alat bukti, dan bukti P.2 yang merupakan akta autentik sesuai Pasal 285 RBg mempunyai kekuatan pembuktian yang sempurna dan mengikat;"
    ELSE
      "<mark>[HURUF ALASAN PERCERAIAN BELUM DIPILIH]</mark>"
  END AS data
) b,
-- Huruf alasan H (murtad), paket abt-murtad-8529-30okt: paragraf tambahan; kalimat bukti surat di atas tidak diubah.
(SELECT m.hH, m.mp,
  CASE WHEN m.hH = 0 THEN NULL
    WHEN m.mp IS NULL THEN "<mark>[AGAMA PIHAK YANG MURTAD BELUM DIUBAH DI SIPP]</mark>"
    WHEN m.bk = 1 THEN CONCAT("Menimbang, bahwa dalil ", m.mp, " telah keluar dari agama Islam (<i>murtad</i>) dan ", m.pag, " dikuatkan oleh bukti surat tentang perpindahan agama ", m.mp, " yang telah bermeterai cukup dan dicocokkan dengan aslinya, serta oleh keterangan saksi-saksi #0046# yang saling bersesuaian, sehingga harus dinyatakan terbukti bahwa ", m.mp, " telah keluar dari agama Islam;")
    ELSE CONCAT("Menimbang, bahwa meskipun tidak diajukan bukti surat tentang perpindahan agama ", m.mp, ", keterangan saksi-saksi #0046# yang saling bersesuaian dan berdasarkan pengetahuan saksi sendiri menerangkan bahwa ", m.mp, " telah keluar dari agama Islam (<i>murtad</i>) dan ", m.pag, ", sehingga harus dinyatakan terbukti bahwa ", m.mp, " telah keluar dari agama Islam;")
  END AS murtad
 FROM (SELECT x.hH, x.bk,
    CASE WHEN x.ag1 <> 1 THEN "#0046#" WHEN x.ag2 <> 1 THEN "#0047#"
      WHEN x.ps REGEXP '#0046#( yang| telah| sudah| kini| kemudian| pun| saat ini| sekarang| sejak [^,.;]{1,40}| hingga [^,.;]{1,30})* (keluar dari agama islam|murtad|berpindah agama|pindah agama|pindah ke agama|kembali (memeluk|ke) agama|masuk agama|memeluk agama (kristen|katolik|katholik|protestan|hindu|buddha|budha|konghucu|khonghucu)|beragama (kristen|katolik|katholik|protestan|hindu|buddha|budha|konghucu|khonghucu))' AND x.ps NOT REGEXP '#0047#( yang| telah| sudah| kini| kemudian| pun| saat ini| sekarang| sejak [^,.;]{1,40}| hingga [^,.;]{1,30})* (keluar dari agama islam|murtad|berpindah agama|pindah agama|pindah ke agama|kembali (memeluk|ke) agama|masuk agama|memeluk agama (kristen|katolik|katholik|protestan|hindu|buddha|budha|konghucu|khonghucu)|beragama (kristen|katolik|katholik|protestan|hindu|buddha|budha|konghucu|khonghucu))' THEN "#0046#"
      WHEN x.ps REGEXP '#0047#( yang| telah| sudah| kini| kemudian| pun| saat ini| sekarang| sejak [^,.;]{1,40}| hingga [^,.;]{1,30})* (keluar dari agama islam|murtad|berpindah agama|pindah agama|pindah ke agama|kembali (memeluk|ke) agama|masuk agama|memeluk agama (kristen|katolik|katholik|protestan|hindu|buddha|budha|konghucu|khonghucu)|beragama (kristen|katolik|katholik|protestan|hindu|buddha|budha|konghucu|khonghucu))' AND x.ps NOT REGEXP '#0046#( yang| telah| sudah| kini| kemudian| pun| saat ini| sekarang| sejak [^,.;]{1,40}| hingga [^,.;]{1,30})* (keluar dari agama islam|murtad|berpindah agama|pindah agama|pindah ke agama|kembali (memeluk|ke) agama|masuk agama|memeluk agama (kristen|katolik|katholik|protestan|hindu|buddha|budha|konghucu|khonghucu)|beragama (kristen|katolik|katholik|protestan|hindu|buddha|budha|konghucu|khonghucu))' THEN "#0047#" END AS mp,
    CASE WHEN x.ag1 <> 1 OR x.ag2 <> 1 THEN CASE x.nag WHEN 'Protestan' THEN 'memeluk agama Kristen Protestan' WHEN 'Katolik' THEN 'memeluk agama Kristen Katolik' WHEN 'Kong Hu Cu' THEN 'memeluk agama Khonghucu' WHEN 'Lainnya' THEN 'memeluk agama lain selain Islam' ELSE CONCAT('memeluk agama ', x.nag) END ELSE CASE WHEN x.ps REGEXP 'protestan' THEN 'memeluk agama Kristen Protestan' WHEN x.ps REGEXP 'katolik|katholik' THEN 'memeluk agama Kristen Katolik' WHEN x.ps REGEXP 'kristen' THEN 'memeluk agama Kristen' WHEN x.ps REGEXP 'hindu' THEN 'memeluk agama Hindu' WHEN x.ps REGEXP 'buddha|budha' THEN 'memeluk agama Buddha' WHEN x.ps REGEXP 'konghucu|khonghucu' THEN 'memeluk agama Khonghucu' ELSE 'memeluk agama lain selain Islam' END END AS pag
  FROM (SELECT IF(z.n <> '' AND z.n NOT REGEXP '[^A-H]' AND INSTR(z.n, 'H') > 0, 1, 0) AS hH,
      (SELECT ph.agama_id FROM perkara_pihak1 pp JOIN pihak ph ON ph.id = pp.pihak_id LEFT JOIN agama ag ON ag.id = ph.agama_id WHERE pp.perkara_id = '#perkara_id#' ORDER BY pp.urutan LIMIT 1) AS ag1,
      (SELECT ph.agama_id FROM perkara_pihak2 pp JOIN pihak ph ON ph.id = pp.pihak_id LEFT JOIN agama ag ON ag.id = ph.agama_id WHERE pp.perkara_id = '#perkara_id#' ORDER BY pp.urutan LIMIT 1) AS ag2,
      CASE WHEN (SELECT ph.agama_id FROM perkara_pihak1 pp JOIN pihak ph ON ph.id = pp.pihak_id LEFT JOIN agama ag ON ag.id = ph.agama_id WHERE pp.perkara_id = '#perkara_id#' ORDER BY pp.urutan LIMIT 1) <> 1 THEN (SELECT ag.nama FROM perkara_pihak1 pp JOIN pihak ph ON ph.id = pp.pihak_id LEFT JOIN agama ag ON ag.id = ph.agama_id WHERE pp.perkara_id = '#perkara_id#' ORDER BY pp.urutan LIMIT 1) ELSE (SELECT ag.nama FROM perkara_pihak2 pp JOIN pihak ph ON ph.id = pp.pihak_id LEFT JOIN agama ag ON ag.id = ph.agama_id WHERE pp.perkara_id = '#perkara_id#' ORDER BY pp.urutan LIMIT 1) END AS nag,
      IFNULL((SELECT p.posita FROM perkara p WHERE p.perkara_id = '#perkara_id#'), '') AS ps,
      IF(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag.abt_data_teks WHERE no_var=1214 AND perkara_id='#perkara_id#') USING utf8),'\\','/'),'"','&quot;'),'''','&#39;'),'') REGEXP 'pindah agama|perpindahan agama|keluar dari agama|masuk agama|baptis|sidi|sudhi wadani|sudi wadani|surat keterangan gereja|surat keterangan agama|sertifikat (baptis|sidi)', 1, 0) AS bk
    FROM (SELECT CASE WHEN UPPER(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag.abt_data_teks WHERE no_var=8503 AND perkara_id='#perkara_id#') USING utf8),'\\','/'),'"','&quot;'),'''','&#39;'),''))) IN ('FASAKH', 'MURTAD') THEN 'H' ELSE REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(UPPER(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag.abt_data_teks WHERE no_var=8503 AND perkara_id='#perkara_id#') USING utf8),'\\','/'),'"','&quot;'),'''','&#39;'),''))), 'DAN', ''), '&', ''), ',', ''), ' ', ''), '+', ''), '/', ''), '.', ''), '-', '') END AS n) z
  ) x
 ) m
) m;
